<?php
declare(strict_types=1);
require_once __DIR__ . '/../backend/config/ocr_auth.php'; apply_security_headers(); start_app_session(); $user=ocr_require_user();
if(empty($_SESSION['csrf_token'])) $_SESSION['csrf_token']=bin2hex(random_bytes(32));
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;
$q=database()->prepare('SELECT p.*, (SELECT pt.numero FROM proveedor_telefono pt WHERE pt.id_proveedor=p.id_proveedor ORDER BY pt.id_telefono LIMIT 1) telefono FROM proveedor p WHERE p.id_proveedor=:id AND p.dni_usuario_registro=:dni LIMIT 1');$q->execute(['id'=>$id,'dni'=>$user['sub']]);$provider=$q->fetch();
if(!$provider){http_response_code(404);exit('No puedes editar este proveedor o ya no existe.');}
$categories=database()->query('SELECT id_categoria,nombre FROM categoria ORDER BY nombre')->fetchAll();$flash=$_SESSION['proveedor_flash']??'';unset($_SESSION['proveedor_flash']);
$esc=static fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Editar proveedor | Biblioteca de Proveedores CAP</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f5f6f8}.panel{max-width:800px;margin:2rem auto;background:white;border-radius:1rem;box-shadow:0 10px 35px #0000000c}.cap{background:#c62828;color:#fff}@media(max-width:575px){.panel{margin:1rem auto}}</style><link href="../assets/css/mobile-header.css?v=4" rel="stylesheet"></head><body><header class="bg-white border-bottom"><nav class="container py-3 d-flex justify-content-between align-items-center"><a class="d-flex align-items-center gap-2 text-decoration-none" href="index.php" aria-label="Inicio CAP"><img src="../assets/img/cap-emblem.svg" width="40" height="44" alt=""><span class="text-danger fw-bold fs-4" style="letter-spacing:.08em">CAP</span></a><h1 class="h4 text-danger mb-0">Editar proveedor</h1><a href="perfil.php" class="btn btn-outline-secondary">Perfil</a></nav></header><main class="container panel p-3 p-md-5">
<?php if($flash!==''):?><div class="alert alert-warning"><?= $esc($flash) ?></div><?php endif;?>
<form action="../backend/controllers/actualizar_proveedor.php" method="post"><input type="hidden" name="csrf_token" value="<?= $esc($_SESSION['csrf_token']) ?>"><input type="hidden" name="id_proveedor" value="<?= (int)$provider['id_proveedor'] ?>"><div class="row g-3"><div class="col-md-8"><label class="form-label" for="name">Nombre *</label><input class="form-control" id="name" name="nombre_empresa" maxlength="150" required value="<?= $esc($provider['nombre_empresa']) ?>"></div><div class="col-md-4"><label class="form-label" for="rtn">RTN</label><input class="form-control" id="rtn" name="rtn" inputmode="numeric" maxlength="14" pattern="[0-9]{14}" value="<?= $esc($provider['rtn']) ?>"></div><div class="col-md-6"><label class="form-label" for="category">Categoría *</label><select class="form-select" id="category" name="id_categoria" required><?php foreach($categories as $cat):?><option value="<?= (int)$cat['id_categoria'] ?>" <?= (int)$provider['id_categoria']===(int)$cat['id_categoria']?'selected':'' ?>><?= $esc($cat['nombre']) ?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label" for="phone">Teléfono (8 dígitos)</label><input class="form-control" id="phone" name="telefono" inputmode="numeric" maxlength="8" pattern="[23789][0-9]{7}" value="<?= $esc($provider['telefono']) ?>"></div><div class="col-md-6"><label class="form-label" for="email">Correo público</label><input class="form-control" id="email" type="email" name="correo" maxlength="120" value="<?= $esc($provider['correo']) ?>"></div><div class="col-12"><label class="form-label" for="address">Dirección</label><input class="form-control" id="address" name="direccion" maxlength="255" value="<?= $esc($provider['direccion']) ?>"></div></div><div class="d-flex justify-content-end gap-2 mt-4"><a class="btn btn-outline-secondary" href="perfil.php">Cancelar</a><button class="btn cap" type="submit">Guardar cambios</button></div></form></main><script>document.querySelector('#rtn').addEventListener('input',e=>e.target.value=e.target.value.replace(/\D/g,'').slice(0,14));document.querySelector('#phone').addEventListener('input',e=>e.target.value=e.target.value.replace(/\D/g,'').slice(0,8));</script></body></html>
